mapper.select:
SELECT EXISTS (
  SELECT 1
    FROM chapter_media_heads cmh
    JOIN generation_jobs gj ON gj.id = cmh.generation_job_id
   WHERE cmh.chapter_id = #{chapterId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
     AND gj.media_plan_id = #{mediaPlanId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler}
     AND gj.media_plan_revision = #{mediaPlanRevision}
)
